solution.solution.cpp:
#include <charconv>
#include <expected>
#include <string>
#include <string_view>

enum class AgeError { empty, notANumber, outOfRange };

std::expected<int, AgeError> parseAge(std::string_view text)
{
    if (text.empty())
    {
        return std::unexpected{ AgeError::empty };
    }
    int value{};
    const char* const last{ text.data() + text.size() };
    const auto [end, error]{ std::from_chars(text.data(), last, value) };
    if (error == std::errc::result_out_of_range)
    {
        return std::unexpected{ AgeError::outOfRange };
    }
    if (error != std::errc{} || end != last)
    {
        return std::unexpected{ AgeError::notANumber };
    }
    if (value < 0 || value > 150)
    {
        return std::unexpected{ AgeError::outOfRange };
    }
    return value;
}

std::string report(const std::expected<int, AgeError>& result)
{
    if (result)
    {
        return "age " + std::to_string(*result);
    }
    switch (result.error())
    {
    case AgeError::empty:      return "error: empty";
    case AgeError::notANumber: return "error: not a number";
    case AgeError::outOfRange: return "error: out of range";
    }
    return "error";
}

unitTests:
TEST("valid ages") { CHECK(parseAge("42").has_value()); CHECK_EQ(parseAge("42").value(), 42); CHECK_EQ(parseAge("0").value(), 0); CHECK_EQ(parseAge("150").value(), 150); }
TEST("each kind of error") { CHECK(parseAge("").error() == AgeError::empty); CHECK(parseAge("abc").error() == AgeError::notANumber); CHECK(parseAge("4x").error() == AgeError::notANumber); CHECK(parseAge("151").error() == AgeError::outOfRange); CHECK(parseAge("-1").error() == AgeError::outOfRange); CHECK(parseAge("99999999999").error() == AgeError::outOfRange); }
TEST("report") { CHECK_EQ(report(parseAge("42")), "age 42"); CHECK_EQ(report(parseAge("")), "error: empty"); CHECK_EQ(report(parseAge("old")), "error: not a number"); CHECK_EQ(report(parseAge("999")), "error: out of range"); }

